\label{thm:long-range}
Under \eqref{eq:power-law-hypothesis}, at every fixed spin,
\begin{equation}
 \lim_{\beta\to\infty}
 \frac{f_J(\beta,S,0)}{f_J^{\rm sw}(\beta,S)}=1.
 \label{eq:main-spin-wave-equivalence}
\end{equation}

\label{thm:long-range-weak-field}
Under \eqref{eq:power-law-hypothesis}, for \(0<\sigma<2\),
\begin{equation}
 \lim_{\beta\to\infty}\sup_{h\geq0}
 \left|
 \beta^{1+2/\sigma}S^{2/\sigma}f_J(\beta,S,h)
 +D_\sigma\operatorname{Li}_{1+2/\sigma}(e^{-\beta h})
 \right|=0.
 \label{eq:stable-long-range-limit}
\end{equation}
For \(\sigma=2\),
\begin{equation}
 \lim_{\beta\to\infty}\sup_{h\geq0}
 \left|
 \beta^2S\log(\beta S)f_J(\beta,S,h)
 +D_2\operatorname{Li}_2(e^{-\beta h})
 \right|=0.
 \label{eq:marginal-long-range-limit}
\end{equation}

\label{thm:finite-variance-infinite-range}
Under the rank-two and finite-second-moment assumptions
\eqref{eq:general-kernel-hypotheses} and \eqref{eq:finite-variance-hypothesis},
\begin{equation}
 \lim_{\beta\to\infty}\ \sup_{h\geq0}
 \left|
  \beta^2S\widetilde j_J f_J(\beta,S,h)
  +\frac1{4\pi}\operatorname{Li}_2(e^{-\beta h})
 \right|=0.
 \label{eq:finite-variance-infinite-range-limit}
\end{equation}

\label{prop:finite-range-quantitative}
There are constants \(C_{S,J}<\infty\)
and \(t_{S,J}<\infty\) such that, for \(t\geq t_{S,J}\) and \(h\geq0\),
\begin{equation}
 \left|
  \beta^2Sj_J f_J(\beta,S,h)
  +\frac{1}{4\pi}\operatorname{Li}_2(e^{-\beta h})
 \right|
 \leq C_{S,J}\,t^{-1/27}(\log t)^{17}.
 \label{eq:main-quantitative}
\end{equation}

\label{lem:finite-range-core-geometry}
There are constants \(c_J,C_J>0\) such that, for every \(L\geq3\),
\(G_L^J\) and every one-vertex deletion of it are connected and
\begin{align}
 \operatorname{gap}(K_{G_L^J})&\geq c_JL^{-2},
 \label{eq:core-volume-gap}\\
 \max_{x,y\in B_L}R_{\rm eff}^{G_L^J}(x,y)
 &\leq C_J\log(2L).
 \label{eq:core-resistance}
\end{align}
Moreover, for every \(a\in B_L\), the punctured graph
\(G_L^J\setminus\{a\}\) is connected and
\begin{equation}
 \max_{x,y\in B_L\setminus\{a\}}
 R_{\rm eff}^{G_L^J\setminus\{a\}}(x,y)
 \leq C_J\log(2L).
 \label{eq:core-punctured-resistance}
\end{equation}
The same conclusions hold for the decorated graph, with constants also
depending on \(r\).

\label{lem:resistance-point-trace}
For every \(g:V\to\mathcal K\) and \(x\in V\),
\begin{equation}
 \|g(x)\|_{\mathcal K}^2
 \leq\frac2n\sum_{y\in V}\|g(y)\|_{\mathcal K}^2
      +2\rho(G)\mathcal E_G(g).
 \label{eq:resistance-point-trace}
\end{equation}

\label{prop:abstract-graph-collision}
For every \(1\leq k\leq n/2\),
\begin{align}
 0\leq N_{G,k}
 \leq{}&Ck^2\left(\frac1{n\lambda}+\rho(G)\right)
 \notag\\[-1mm]
 &\times\left[1+C\Delta\left(
       \frac{k^2}{n\lambda}+k\rho_\circ(G)\right)\right]^2
 H_{G,k}^2.
 \label{eq:abstract-graph-collision}
\end{align}
The constant \(C\) is numerical, and the inequality is understood in the
quadratic-form sense.

For \(i<j\), denote by \(q_{ij}(F)\) the part of the product Dirichlet
form carried by product edges having an endpoint on
\(\{x_i=x_j\}\).  We claim that
\begin{equation}
 q_{ij}(F)\leq C\left(\frac1{n\lambda}+\rho(G)\right)
 \|L_0F\|^2.
 \label{eq:single-diagonal-point-trace}
\end{equation}
Consider first an edge in coordinate \(i\), orient its base edge
\(e=(x,x')\) from the diagonal endpoint, freeze all other variables, and
apply Lemma~\ref{lem:resistance-point-trace} to
\begin{equation}
 g(y):=\sqrt{c_{xx'}}
 \bigl[F(\ldots,x',\ldots,y,\ldots)
       -F(\ldots,x,\ldots,y,\ldots)\bigr].
 \label{eq:normal-point-trace-function}
\end{equation}
After summation, the mean term is at most
\begin{equation}
 \frac Cn\langle F,K_iF\rangle
 \leq\frac C{n\lambda}\|L_0F\|^2,
 \label{eq:normal-point-trace-mean}
\end{equation}
because \(K_i\leq\lambda^{-1}K_i^2\leq
\lambda^{-1}L_0^2\).  The fluctuation term is
\begin{equation}
 C\rho(G)\langle F,K_iK_jF\rangle
 \leq\frac{C\rho(G)}4\|L_0F\|^2.
 \label{eq:normal-point-trace-fluctuation}
\end{equation}
The channel in coordinate \(j\) is identical.  For tangential edges one
must sum the spectator coordinates before estimating.  With
\begin{equation}
 A_{\rm sp}:=\sum_{\ell\ne i,j}K_\ell,
 \label{eq:spectator-operator}
\end{equation}
their total mean term is bounded as in
\eqref{eq:normal-point-trace-mean}, while their fluctuation term is
\begin{equation}
 C\rho(G)\langle F,K_jA_{\rm sp}F\rangle
 \leq\frac{C\rho(G)}4
 \langle F,(K_j+A_{\rm sp})^2F\rangle
 \leq\frac{C\rho(G)}4\|L_0F\|^2.
 \label{eq:tangential-point-trace-fluctuation}
\end{equation}
This aggregation is what prevents an extra factor \(k\).  Equations
\eqref{eq:normal-point-trace-mean}--
\eqref{eq:tangential-point-trace-fluctuation} prove
\eqref{eq:single-diagonal-point-trace}.  Summing over fewer than \(k^2/2\)
pairs gives
\begin{equation}
 q_{\rm bad}(F)\leq a_G\|L_0F\|^2,
 \qquad
 a_G:=Ck^2\left(\frac1{n\lambda}+\rho(G)\right).
 \label{eq:abstract-bad-edge-bound}
\end{equation}

We next prove the first-order estimate, including its normalization.  Let
\(\nu_k\) be the uniform probability measure on the \(k\)-subsets of
\(V\), and use the corresponding normalized inner product.  Since this
only multiplies the counting inner product by a scalar, the resulting
operator inequalities are unchanged.  Put \(N_k=\binom nk\),
\(q=n-k+1\), and, for \(b\in A\), set \(B=A\setminus\{b\}\) and
\begin{equation}
 \overline f_B:=\frac1q\sum_{y\notin B}f(B\cup\{y\}).
 \label{eq:abstract-contact-average}
\end{equation}
Jensen's inequality gives
\begin{equation}
 |f(A)|^2\leq2|\overline f_B|^2
 +\frac2q\sum_{y\notin B}
 |f(A)-f(B\cup\{y\})|^2.
 \label{eq:abstract-contact-jensen}
\end{equation}
For \(d_A(b):=\sum_{a\in A}c_{ab}\), average
\eqref{eq:abstract-contact-jensen} with weight \(d_A(b)\) over
\(A\) and \(b\in A\).  Denote by \(M\) and \(F\) the averaged
contributions of the mean and fluctuation terms in
\eqref{eq:abstract-contact-jensen}, respectively.  This yields
\begin{equation}
 \langle f,R_{G,k}f\rangle_{\nu_k}\leq2M+2F.
 \label{eq:abstract-contact-split}
\end{equation}
The change of variables \(A=B\cup\{b\}\), followed by Jensen once
more, gives
\begin{align}
 M
 &\leq\frac1{N_kq}
 \sum_{|B|=k-1}\left(\sum_{b\notin B}\sum_{a\in B}c_{ab}\right)
 \sum_{y\notin B}|f(B\cup\{y\})|^2\notag\\
 &\leq\frac{\Delta k(k-1)}q\|f\|_{\nu_k}^2
 \leq\frac{2\Delta k^2}{n}\|f\|_{\nu_k}^2.
 \label{eq:abstract-contact-mean}
\end{align}

For the fluctuation term use the occupied neighbour \(a\) of \(b\) as
an anchor.  Conditional on \(a\in A\), the set
\(\zeta=A\setminus\{a\}\) is uniform among the \((k-1)\)-subsets of
\(V\setminus\{a\}\).  Denote this law by \(\nu_{k-1}^{(a)}\), put
\(f_a(\zeta)=f(\zeta\cup\{a\})\), and set
\begin{equation}
 \mathcal E_a(f_a):=
 \langle f_a,H_{G\setminus\{a\},k-1}f_a\rangle_{\nu_{k-1}^{(a)}}.
 \label{eq:abstract-conditioned-energy}
\end{equation}
Directly rearranging the fluctuation sum in
\eqref{eq:abstract-contact-split} gives
\begin{align}
 F={}&\frac{k}{nq}\sum_{a\in V}\sum_{b\ne a}c_{ab}
 \sum_{y\ne a}\mathbb E_{\nu_{k-1}^{(a)}}\!\left[
 \1_{\{b\in\zeta,\ y\notin\zeta\}}
 \left|f_a(\zeta\setminus\{b\}\cup\{y\})-f_a(\zeta)\right|^2
 \right].
 \label{eq:abstract-contact-conditioned}
\end{align}
Chen's weighted moving-particle lemma \cite{Chen2017}
bounds the expectation in \eqref{eq:abstract-contact-conditioned} by
\(R_{\rm eff}^{G\setminus\{a\}}(b,y)\mathcal E_a(f_a)\).  Indeed, swap invariance
identifies the one-orientation indicator expectation in
\eqref{eq:abstract-contact-conditioned} with one half of the full swap
expectation in Chen's normalization, so no extra factor is present.  Hence,
using
\(q\geq n/2\) and \(\sum_bc_{ab}\leq\Delta\),
\begin{equation}
 F\leq C\frac{k\Delta\rho_\circ(G)}n
       \sum_{a\in V}\mathcal E_a(f_a).
 \label{eq:abstract-contact-fluctuation}
\end{equation}
Every allowed exclusion move is present in the conditioned energy for
exactly \(k-1\) occupied anchors.  Since
\(\binom nk/\binom{n-1}{k-1}=n/k\), the normalized forms satisfy the
exact identity
\begin{equation}
 \frac{k}{n}\sum_{a\in V}\mathcal E_a(f_a)
 =(k-1)\langle f,H_{G,k}f\rangle_{\nu_k}.
 \label{eq:anchored-energy-identity}
\end{equation}
Combining \eqref{eq:abstract-contact-split},
\eqref{eq:abstract-contact-mean},
\eqref{eq:abstract-contact-fluctuation}, and
\eqref{eq:anchored-energy-identity} proves
\begin{equation}
 \langle f,R_{G,k}f\rangle_{\nu_k}
 \leq C\Delta\frac{k^2}{n}\|f\|_{\nu_k}^2
      +C\Delta k\rho_\circ(G)
       \langle f,H_{G,k}f\rangle_{\nu_k}.
 \label{eq:abstract-contact-bound}
\end{equation}

The exclusion gap equals \(\lambda\): the lower bound follows from the
interchange-process theorem of Caputo, Liggett and Richthammer
\cite{CaputoLiggettRichthammer2010}, and the reverse bound is obtained by
lifting a one-particle eigenfunction.  Since \(N_{G,k}\leq R_{G,k}\),
\eqref{eq:abstract-contact-bound} therefore implies, off the constants,
\begin{equation}
 N_{G,k}\leq b_GH_{G,k},\qquad
 b_G:=C\Delta\left(\frac{k^2}{n\lambda}
                         +k\rho_\circ(G)\right).
 \label{eq:abstract-first-order-collision}
\end{equation}

Apply \eqref{eq:abstract-bad-edge-bound} to the harmonic extension of
\(f\).  The identities \eqref{eq:extension-energy}--
\eqref{eq:collision-as-bad-energy} are purely graph-theoretic and give
\begin{equation}
 N_{G,k}\leq a_G(H_{G,k}+N_{G,k})^2.
 \label{eq:abstract-preabsorbed-collision}
\end{equation}
Put \(\mathcal K=H_{G,k}^{-1/2}N_{G,k}H_{G,k}^{-1/2}\) off the constants.
Then \(0\leq\mathcal K\leq b_G\), and congruence of
\eqref{eq:abstract-preabsorbed-collision}, followed by congruence with
\((I+\mathcal K)^{-1}\), yields
\(\mathcal K(I+\mathcal K)^{-2}\leq a_GH_{G,k}\).
The scalar inequality
\(x\leq(1+b_G)^2x(1+x)^{-2}\) for \(0\leq x\leq b_G\)
proves \eqref{eq:abstract-graph-collision}.  Both sides vanish on the
constants, so the result holds on the full space.

\label{prop:finite-range-collision}
For \(L\geq3\) and \(1\leq k\leq rL^2/2\),
\begin{equation}
 0\leq N_{L,k}^{(r,J)}
 \leq C_{S,J}k^6\log^3(2L)
       \bigl(H_{L,k}^{(r,J)}\bigr)^2.
 \label{eq:finite-range-quadratic-collision}
\end{equation}

For the decorated free-box graph, Lemma~\ref{lem:finite-range-core-geometry}
gives \(n=rL^2\), \(\lambda\geq c_{S,J}L^{-2}\),
\(\rho,\rho_\circ\leq C_{S,J}\log(2L)\), and
\(\Delta\leq C_{S,J}\).  Proposition~\ref{prop:abstract-graph-collision}
then gives
\begin{align*}
 N_{L,k}^{(r,J)}
 &\leq C_{S,J}k^2\log(2L)
       \bigl(1+C_{S,J}k^2\log(2L)\bigr)^2
       \bigl(H_{L,k}^{(r,J)}\bigr)^2\\
 &\leq C_{S,J}k^6\log^3(2L)
       \bigl(H_{L,k}^{(r,J)}\bigr)^2,
\end{align*}
where the case \(k=1\) is immediate.

\label{lem:finite-range-heat-trace}
There are \(c_J,C_J>0\) such that, for \(L\geq3\) and
\(1\leq u\leq L^2\),
\begin{align}
 \operatorname{Tr} e^{-uK_{J,L}^N}-1
 &\leq L^2I_J(u)+C_J\left(\frac L{\sqrt u}+1\right),
 \label{eq:finite-range-neumann-heat}\\
 \operatorname{Tr} e^{-uh_{J,L}^D}
 &\geq L^2I_J(u)-C_J\left(\frac L{\sqrt u}+1\right).
 \label{eq:finite-range-dirichlet-heat}
\end{align}
Moreover,
\begin{equation}
 I_J(u)=\frac1{4\pi u\sqrt{\det A_J}}+O_J(u^{-2}),
 \qquad u\geq1,
 \label{eq:finite-range-local-clt}
\end{equation}
and, for \(u\geq L^2\),
\begin{equation}
 \operatorname{Tr}_{\1^\perp}e^{-uK_{J,L}^N}
 +\operatorname{Tr} e^{-uh_{J,L}^D}
 \leq C_J e^{-c_Ju/L^2}.
 \label{eq:finite-range-large-time-heat}
\end{equation}

Let \(p_{L,u}^N\), \(p_{L,u}^D\), and \(p_{\infty,u}\) denote the
censored, killed, and full-lattice heat kernels, respectively.  Choose
\begin{equation}
 D>2\sup_{L,x}\sum_{y\in B_L}J(y-x),
 \qquad P_L:=I-D^{-1}K_{J,L}^N.
 \label{eq:finite-range-uniformization}
\end{equation}
Equivalently, add at \(x\) a self-loop of weight
\(D-\sum_{y\in B_L}J(y-x)\).  Then \(P_L\) is a lazy symmetric Markov
kernel with invariant counting measure.  The coordinate nearest-neighbour
conductances are bounded below by \(j_{\rm bb}>0\), all jumps have length
at most \(R_J\), and hence the graph metric is uniformly comparable with
the lattice metric.  Boundary balls in \(B_L\) have uniform volume
doubling.  The nearest-neighbour Poincar\'e inequality, together with
\(K_{J,L}^N\geq j_{\rm bb}K_L^{\rm nn}\), gives the scale-invariant
Poincar\'e inequality on these balls.  Delmotte's theorem
\cite{Delmotte1999}, applied to \(P_L\) and followed by Poissonization,
therefore gives, for \(1\leq v\leq L^2\),
\begin{equation}
 p_{L,v}^N(x,y)\leq C_J\left[
 v^{-1}e^{-c_J\min\{|x-y|^2/v,|x-y|\}}+L^{-2}\right].
 \label{eq:finite-range-gaussian-bound}
\end{equation}
The same construction on \(\mathbb Z^2\) gives the full-lattice estimate without
the \(L^{-2}\) term, and domination by the full-lattice walk gives the
killed estimate.

We now prove the boundary comparison.  Realize the full-lattice walk by
Poisson clocks for the jumps in \(\mathcal S_J\).  The censored walk uses
the same clocks but rejects a jump leaving \(B_L\).  The two paths agree
until the first such clock ring.  Set
\begin{equation}
 \delta_{J,L}(x):=\max\{0,\operatorname{dist}_\infty
 (x,\mathbb Z^2\setminus B_L)-R_J\}.
 \label{eq:finite-range-boundary-distance}
\end{equation}
Symmetry and finite range imply, for every coordinate direction and
\(0\leq\theta\leq1\),
\begin{equation}
 \sum_zJ(z)(e^{\theta z_\nu}-1)\leq C_J\theta^2.
 \label{eq:finite-range-exponential-moment}
\end{equation}
Optimize Doob's inequality for the exponential supermartingale at
\begin{equation*}
 \theta=\min\{\delta_{J,L}(x)/(2C_Ju),1\}.
\end{equation*}
This gives
\begin{equation}
 \begin{aligned}
 &\mathbb P_x(\text{a boundary jump is attempted before }u)\\
 &\qquad\leq C_J\exp\!\left[-c_J\min\left\{
 \frac{\delta_{J,L}(x)^2}{u},\delta_{J,L}(x)\right\}\right].
 \end{aligned}
 \label{eq:finite-range-exit-probability}
\end{equation}

Let \(X\) be the full-lattice walk and \(Y\) the censored walk in this
common-clock construction, and let \(T\) be the first clock ring that
would leave \(B_L\).  Regard rejected rings of \(Y\) as marks.  The
contributions of paths with \(T>u\) agree, and hence
\begin{align}
 |p_{L,u}^N(x,x)-p_{\infty,u}(0,0)|
 \leq{}&\mathbb P_x(Y_u=x,T\leq u)
       +\mathbb P_x(X_u=x,T\leq u).
 \label{eq:finite-range-coupling-difference}
\end{align}
For either term, write \(p_v\) for the transition kernel of the
corresponding walk.  The contribution with \(T\leq u/2\) is, by the strong
Markov property and \eqref{eq:finite-range-gaussian-bound}, at most
\begin{equation}
 \mathbb P_x(T\leq u/2)\sup_{v\geq u/2,z}p_v(z,x)
 \leq\frac{C_J}{u}\mathbb P_x(T\leq u/2).
 \label{eq:finite-range-early-boundary-event}
\end{equation}
For \(1\leq u\leq2\), the final inequality follows from \(p_v\leq1\)
after enlarging \(C_J\). Otherwise it follows from
\eqref{eq:finite-range-gaussian-bound}, with \(L^{-2}\leq2/u\).
Reversal of diagonal loops bounds the contribution of an event in
\([u/2,u]\) by the same expression.  For \(Y\), this is reversal of the
marked rejected-clock path measure. For \(X\), it is ordinary
reversibility.  Before \(T\) the two constructions coincide, so
\(\mathbb P_x(T\leq u/2)\) is bounded by
\eqref{eq:finite-range-exit-probability}.  Thus, for
\(\mathrm{bc}\in\{N,D\}\) and \(1\leq u\leq L^2\),
\begin{equation}
 \left|p_{L,u}^{\mathrm{bc}}(x,x)-p_{\infty,u}(0,0)\right|
 \leq\frac{C_J}{u}
 \exp\!\left[-c_J\min\left\{
 \frac{\delta_{J,L}(x)^2}{u},\delta_{J,L}(x)\right\}\right].
 \label{eq:not-feeling-boundary}
\end{equation}
Indeed, for the killed kernel,
\begin{equation}
 p_{\infty,u}(0,0)-p_{L,u}^D(x,x)
 =\mathbb P_x(X_u=x,T\leq u),
 \label{eq:finite-range-killed-difference}
\end{equation}
so the same early/late argument also gives the one-sided sign.  The second
term in the minimum in \eqref{eq:not-feeling-boundary} is the bounded-jump
correction.  There are \(O(L)\) sites in each boundary layer and
\begin{equation}
 \sum_{m\geq0}e^{-c_J\min\{m^2/u,m\}}\leq C_J(\sqrt u+1).
 \label{eq:finite-range-boundary-layer-sum}
\end{equation}
Summing \eqref{eq:not-feeling-boundary} therefore gives
\(C_JL/\sqrt u+C_J\).  This proves
\eqref{eq:finite-range-neumann-heat} and
\eqref{eq:finite-range-dirichlet-heat}.

The backbone hypothesis \eqref{eq:backbone-hypothesis} makes zero
the unique minimum of
\(\varepsilon_J\) on the Brillouin torus.  Near zero,
\begin{equation}
 \varepsilon_J(p)=p^{\mathrm T}A_Jp+O_J(|p|^4),
 \label{eq:finite-range-symbol-taylor}
\end{equation}
whereas it is bounded below away from zero off a fixed neighbourhood.
Splitting the integral into this neighbourhood and its complement, Taylor
expansion near zero and Gaussian tail bounds prove
\eqref{eq:finite-range-local-clt}.  At \(u=L^2\),
\eqref{eq:finite-range-neumann-heat} bounds the nonconstant Neumann trace,
while domination of the killed kernel by the full-lattice kernel bounds
the Dirichlet trace.  The gap in \eqref{eq:core-volume-gap}, the
Dirichlet Poincar\'e inequality following from
\eqref{eq:finite-range-dirichlet-form}, and the semigroup property then
give \eqref{eq:finite-range-large-time-heat}.

\label{lem:finite-range-bose-trace}
For \(1\leq s\leq L^2\), uniformly in \(a\geq0\),
\begin{align}
 \Phi_{J,L}^N(s,a)
 &\leq\frac{L^2}{4\pi s\sqrt{\det A_J}}
       \operatorname{Li}_2(e^{-a})+C_J\mathcal R_L(s),
 \label{eq:finite-range-neumann-bose}\\
 \Phi_{J,L}^D(s,a)
 &\geq\frac{L^2}{4\pi s\sqrt{\det A_J}}
       \operatorname{Li}_2(e^{-a})-C_J\mathcal R_L(s),
 \label{eq:finite-range-dirichlet-bose}
\end{align}

\label{prop:finite-range-pressure}
For all sufficiently large \(t\) and every \(h\geq0\),
\begin{equation}
 \beta^2Sj_J f_J(\beta,S,h)
 \geq-\frac1{4\pi}\operatorname{Li}_2(e^{-\beta h})
       -C_{S,J}t^{-1/27}(\log t)^{17}.
 \label{eq:finite-range-pressure-direction}
\end{equation}

Let \(j_*:=\min\{\gamma(e_1),\gamma(e_2)\}>0\). Comparison with the
unit-coupling nearest-neighbour exchange and
\cite{Klippel2026}, in the same normalization of the decorated
Hamiltonian, give
\begin{equation}
 H_{m,k}^{(r,\gamma),\mathrm{HW}}\geq c_{S,J}\frac{k}{m^2}.
 \label{eq:finite-range-rough-sector}
\end{equation}
The multiplicity at deficit \(k\) is at most \(\binom{rm^2}{k}\), so
\eqref{eq:exact-field-multiplet-decomposition} gives
\[
 \operatorname{Tr} e^{-u\mathcal H_m^{(r,\gamma)}-a\mathcal N}
 \leq(rm^2+1)\exp\{rm^2e^{-c_{S,J}u/m^2-a}\}.
\]

Choose, up to bounded integer rounding factors,
\begin{equation}
 g:=t^b,\qquad L^2\asymp tg,\qquad
 m^2\asymp\frac{t}{A_{S,J}\log t},
 \label{eq:finite-range-pressure-scales}
\end{equation}
where \(0<b<1/13\) and \(A_{S,J}\) is a sufficiently large fixed
constant. Choose \(m\mid L\), with relative rounding errors tending to
zero. Delete the positive bonds between the \(m\)-cells using
\eqref{eq:duhamel-bond-removal}. The preceding trace bound at \(u=t/2\)
gives
\begin{equation}
 \log\operatorname{Tr} e^{-(t/2)\mathcal H_L^{(r,\gamma)}-a\mathcal N}
 \leq C_{S,J}g(\log t)^2.
 \label{eq:finite-range-rough-trace}
\end{equation}
Set
\begin{equation}
 e_0:=C_{S,J}\frac{g(\log t)^2}{t},\qquad
 K:=\left\lfloor c_{S,J}^{-1}L^2e_0\right\rfloor
 \leq C_{S,J}g^2(\log t)^2.
 \label{eq:finite-range-cutoffs}
\end{equation}
Choose the constant in \(e_0\) larger than twice the one in
\eqref{eq:finite-range-rough-trace}. The scalar inequality
\begin{equation}
 \1_{\{E>e_0\}}e^{-tE-ak}
 \leq e^{-te_0/2}e^{-tE/2-ak}
 \qquad(E\geq0)
 \label{eq:high-energy-spectral-inequality}
\end{equation}
and \eqref{eq:finite-range-rough-trace} show that exchange energies
above \(e_0\) contribute at most
\begin{equation}
 (rL^2+1)e^{-c_{S,J}g(\log t)^2},
 \label{eq:finite-range-high-energy-tail}
\end{equation}
and \eqref{eq:finite-range-rough-sector} excludes \(k>K\) below the
cutoff.

For \(1\leq k\leq K\), let \(P_{k,e_0}^{(r,\gamma)}\) be the spectral
projection of \(H_{L,k}^{(r,\gamma),\mathrm{HW}}\) onto \([0,e_0]\), extended by
zero off the highest-weight multiplicity space.  On its range,
Proposition~\ref{prop:finite-range-collision} gives
\begin{align}
 &P_{k,e_0}^{(r,\gamma)}
 \bigl(H_{L,k}^{(r,\gamma)}+N_{L,k}^{(r,\gamma)}\bigr)
 P_{k,e_0}^{(r,\gamma)}
 \notag\\
 &\qquad\leq(1+\delta_t)P_{k,e_0}^{(r,\gamma)}
 H_{L,k}^{(r,\gamma)}P_{k,e_0}^{(r,\gamma)},
 \label{eq:finite-range-relative-collision}\\[-1mm]
 \delta_t\leq C_{S,J}K^6\log^3(2L)e_0
 \leq C_{S,J}\frac{g^{13}(\log t)^{17}}t.
 \label{eq:finite-range-collision-delta}
\end{align}
Let \(\lambda_{k,j}\leq e_0\) be the retained highest-weight exchange
eigenvalues and \(\mu_{k,j}\) the free symmetric-product eigenvalues,
both ordered increasingly with multiplicity. Harmonic extension is
injective. Equations \eqref{eq:extension-norm}--
\eqref{eq:extension-energy} and min--max therefore give
\(\mu_{k,j}\leq(1+\delta_t)\lambda_{k,j}\). With
\(s=t/(1+\delta_t)\), it follows that
\begin{equation}
 e^{-ak}\sum_{\lambda_{k,j}\leq e_0}e^{-t\lambda_{k,j}}
 \leq e^{-ak}\operatorname{Tr}_{\operatorname{Sym}^k\ell^2(\mathcal V_{L,r})}
 e^{-sL_{0,L,k}^{(r,\gamma)}}.
 \label{eq:fixed-k-field-comparison}
\end{equation}
The field mass \(a\) is unchanged. Since \(b<1/13\),
\eqref{eq:finite-range-collision-delta} gives \(\delta_t=o(1)\).  Hence,
for large \(t\),
\begin{equation}
 1\leq\frac t2\leq s\leq t\leq L^2,
 \label{eq:finite-range-heat-time-range}
\end{equation}
where the final inequality uses \(L^2\asymp tg\) and \(g=t^b\to\infty\).
Thus Lemma~\ref{lem:finite-range-bose-trace} applies. The free box has
one zero mode. Writing \(Z_k^0(s)\) for its field-free canonical trace,
summing the zero-mode occupation up to \(K\) gives
\begin{equation}
 \sum_{k=0}^Ke^{-ak}Z_k^0(s)
 \leq(K+1)\prod_{\eta\in\operatorname{spec}(h_{r,\gamma})\setminus\{0\}}
 (1-e^{-s\eta-a})^{-1}.
 \label{eq:uniform-zero-mode-sum}
\end{equation}
Eigenvalues in the product are counted with multiplicity. Together with
\eqref{eq:descendant-geometric-factor}, this controls the zero mode and
spin descendants uniformly at \(a=0\).

The one-particle decorated operator is
\begin{equation}
 h_{r,\gamma}=K_{\gamma,L}^N\otimes P
             +M_{d_{\gamma,L}}\otimes Q,
 \qquad
 d_{\gamma,L}(x):=\sum_{y\in B_L}\gamma(y-x).
 \label{eq:finite-range-acoustic-optical-split}
\end{equation}
Connectedness and the smallest positive kernel weight imply
\(d_{\gamma,L}(x)\geq c_J\), so the \(r-1\) optical bands contribute
at most \(C_{S,J}L^2e^{-c_Js-a}\).  Insert
Lemma~\ref{lem:finite-range-bose-trace} with
\(\det A_\gamma=1\).  The descendant factor and the truncated zero mode
contribute at most
\(C_{S,J}\log(tg)\) to the logarithm. The retained trace contains the
vacuum and is at least one, so the discarded tail changes its logarithm
by at most \eqref{eq:finite-range-high-energy-tail}.
Since \(L^2\asymp tg\), the resulting box estimate is
\begin{align}
 \frac t{L^2}\log Z_{L,J,h}^{(S)}(\beta)
 \leq{}&\frac1{4\pi}\operatorname{Li}_2(e^{-a})
 \notag\\
 &+C_{S,J}\left[
 \frac{g^{13}(\log t)^{17}}t+g^{-1/2}
 +\frac{\log t}{g}+\frac1t
 +te^{-c_Jt}+te^{-c_Jg(\log t)^2}\right].
 \label{eq:finite-range-box-pressure}
\end{align}
Here \(g^{-1/2}\), \(\log(t)/g\), and \(t^{-1}\) are respectively the
three nonconstant terms in
\eqref{eq:finite-range-bose-remainder} after multiplication by
\(t/L^2\).  Thus no separable eigenbasis has been used.

Tile a large square by \(L\)-boxes and delete the positive bonds between
them.  The one-way inequality is in the required direction by
\eqref{eq:duhamel-bond-removal}, so
\eqref{eq:finite-range-box-pressure} passes to the thermodynamic
pressure.  Choose \(b=2/27\), which balances
\(g^{13}/t\) with \(g^{-1/2}\), and use
\eqref{eq:finite-range-scaling-identity}.  This proves
\eqref{eq:finite-range-pressure-direction}.

\label{lem:general-projected-entropy}
We have \(1-Z_{\mathcal P}/Z_0\leq q\) and
\begin{align}
 \frac1\beta\operatorname{Tr}\Gamma_{\mathcal P}\log\Gamma_{\mathcal P}
 \leq{}&-\frac1\beta\log Z_{\mathcal P}
 -\frac{\operatorname{Tr}_{\mathcal F_\Lambda}K e^{-\beta K}}{Z_{\mathcal P}}
 \notag\\
 &+\frac{Z_0}{2Z_{\mathcal P}}
 \bigl(qE_1+\rho_*E_2\bigr).
 \label{eq:general-projected-entropy}
\end{align}

\label{prop:finite-range-variational}
For all sufficiently large \(t\) and every \(h\geq0\),
\begin{equation}
 \beta^2Sj_J f_J(\beta,S,h)
 \leq-\frac1{4\pi}\operatorname{Li}_2(e^{-\beta h})
       +C_{S,J}t^{-1/3}(\log t)^{2/3}.
 \label{eq:finite-range-variational-direction}
\end{equation}

Use the normalization \eqref{eq:finite-range-normalization}.  On an
active square \(B_\ell\), pin every exterior spin in the state with third
component \(+S\) and define
\begin{align}
 H_{\ell,\gamma,\widehat h}^D
 :={}&\frac12\sum_{x\in B_\ell}
 \sum_{\substack{z\in\mathbb Z^2\\x+z\in B_\ell}}
 \gamma(z)(S^2-\mathbf S_x\cdot\mathbf S_{x+z})
 \notag\\
 &+\sum_{x\in B_\ell}
 \sum_{\substack{z\in\mathbb Z^2\\x+z\notin B_\ell}}
 \gamma(z)S(S-S_x^3)
 +\widehat h\sum_{x\in B_\ell}(S-S_x^3).
 \label{eq:finite-range-dirichlet-spin-hamiltonian}
\end{align}
Its one-particle operator is the zero-exterior form
\eqref{eq:finite-range-dirichlet-form} with \(J\) replaced by
\(\gamma\).
Write
\[
 f_{\ell,\gamma}^{D}(\widehat\beta,S,\widehat h)
 :=-\frac1{\widehat\beta\ell^2}
 \log\operatorname{Tr} e^{-\widehat\beta H_{\ell,\gamma,\widehat h}^D}.
\]

Let
\(\varepsilon_0(p)=2\sum_{\nu=1}^2(1-\cos p_\nu)\).
Near the origin, Taylor's formula and the smallest and largest
eigenvalues of \(A_\gamma\) compare \(\varepsilon_\gamma\) with
\(\varepsilon_0\).  Away from the origin, compactness and the uniqueness
of the zero of \(\varepsilon_\gamma\) give the same two-sided comparison.
Hence
\begin{equation}
 c_J\varepsilon_0(p)\leq\varepsilon_\gamma(p)
 \leq C_J\varepsilon_0(p),\qquad p\in[-\pi,\pi]^2.
 \label{eq:finite-range-symbol-comparison}
\end{equation}
Fourier transformation of the zero extension turns
\eqref{eq:finite-range-symbol-comparison} into a comparison of
Dirichlet forms.  In particular, the nearest-neighbour Green-function
bound gives, uniformly in \(x\in B_\ell\),
\begin{equation}
 \langle\delta_x,(h_{\gamma,\ell}^D)^{-1}\delta_x\rangle
 \leq C_J\log(2\ell).
 \label{eq:finite-range-local-green-bound}
\end{equation}

Adopt the notation of Lemma~\ref{lem:general-projected-entropy} with
\(A=S h_{\gamma,\ell}^D+\widehat h I\) and inverse temperature
\(\widehat\beta\), so that
\(\widehat\beta K=t\,\mathrm d\Gamma(h_{\gamma,\ell}^D)
+a\mathcal N\). Equation~\eqref{eq:trial-operator-inequality} applies
to \(H_{\ell,\gamma,\widehat h}^D\).

No eigenfunction formula is required for the projection errors.  Indeed,
\((e^{t\lambda+a}-1)^{-1}\leq(t\lambda)^{-1}\) and
\eqref{eq:finite-range-local-green-bound} give
\begin{equation}
 \rho_x\leq C_J\frac{\log(2\ell)}t,\qquad
 1-\frac{Z_{\mathcal P}}{Z_0}
 \leq q\leq C_J\frac{\ell^2\log^2(2\ell)}{t^2}.
 \label{eq:finite-range-projection-defect}
\end{equation}
Let \(\lambda_j\) be the ordered eigenvalues of
\(h_{\gamma,\ell}^D\), and let \(\mu_j\) be those of the unit-coupling
nearest-neighbour zero-exterior operator.  By
\eqref{eq:finite-range-symbol-comparison} and min--max,
\(\lambda_j\geq c_J\mu_j\), with \(c_J\leq1\).  The functions
\begin{equation}
 F(u):=\frac{u}{e^u-1},
 \qquad G(u):=\frac{u}{\sinh^2(u/2)}
 \label{eq:finite-range-decreasing-functions}
\end{equation}
are decreasing on \((0,\infty)\), and
\begin{align}
 \frac{2(S\lambda_j+\widehat h)}{e^{t\lambda_j+a}-1}
 &=\frac{2S}{t}F(t\lambda_j+a),
 \label{eq:finite-range-energy-function}\\
 \frac{S\lambda_j+\widehat h}{\sinh^2((t\lambda_j+a)/2)}
 &=\frac{S}{t}G(t\lambda_j+a).
 \label{eq:finite-range-entropy-function}
\end{align}
The nearest-neighbour eigenvalue count and dyadic summation therefore
give, when \(\ell\geq2\sqrt t\),
\begin{align}
 \operatorname{Tr}\frac{2(Sh_{\gamma,\ell}^D+\widehat h)}
 {e^{th_{\gamma,\ell}^D+a}-1}
 &\leq C_{S,J}\frac{\ell^2}{t^2},
 \label{eq:finite-range-energy-sum}\\
 \operatorname{Tr}\frac{Sh_{\gamma,\ell}^D+\widehat h}
 {\sinh^2((th_{\gamma,\ell}^D+a)/2)}
 &\leq C_{S,J}\frac{\ell^2\log(2\ell)}{t^2}.
 \label{eq:finite-range-entropy-sum}
\end{align}
These bounds are uniform in \(a\geq0\). Insert
\eqref{eq:finite-range-projection-defect},
\eqref{eq:finite-range-energy-sum}, and
\eqref{eq:finite-range-entropy-sum} into
\eqref{eq:general-projected-free-energy}. For \(q\leq1/2\), this gives
\begin{align}
 f_{\ell,\gamma}^D(\widehat\beta,S,\widehat h)
 \leq{}&\frac1{\widehat\beta\ell^2}
 \operatorname{Tr}\log(1-e^{-th_{\gamma,\ell}^D-a})
 \notag\\
 &+\frac{C_{S,J}\log^2(2\ell)}{\widehat\beta t^2}
 +\frac{C_{S,J}\ell^2\log^2(2\ell)}{t^4}.
 \label{eq:finite-range-finite-box-variational}
\end{align}

Apply the Dirichlet half of
Lemma~\ref{lem:finite-range-bose-trace} to the logarithmic trace term in
\eqref{eq:finite-range-finite-box-variational}.  Separate
active \(\ell\)-squares by corridors of width \(R_J\).  No bond then
joins two active squares.  Every active-to-corridor bond is exactly a
boundary term in
\eqref{eq:finite-range-dirichlet-spin-hamiltonian}, and a polarized
corridor has zero internal and field energy.  The active density is
\begin{equation}
 \left(\frac\ell{\ell+R_J}\right)^2=1+O_J(\ell^{-1}).
 \label{eq:finite-range-active-density}
\end{equation}
After multiplying by \(S\widehat\beta^2\), equations
\eqref{eq:finite-range-bose-remainder},
\eqref{eq:finite-range-finite-box-variational}, and
\eqref{eq:finite-range-active-density} give
\begin{align}
 \widehat\beta^2S f_\gamma(\widehat\beta,S,\widehat h)
 \leq{}&-\frac1{4\pi}\operatorname{Li}_2(e^{-a})
 \notag\\[-1mm]
 &+C_{S,J}\left[
 \frac{\sqrt t}{\ell}+\frac1\ell
 +\frac{t\log(2+\ell^2/t)}{\ell^2}
 +\frac1t+\frac t{\ell^2}
 +\frac{\log^2(2\ell)}t
 +\frac{\ell^2\log^2(2\ell)}{t^2}
 \right].
 \label{eq:finite-range-variational-errors}
\end{align}
Choose
\begin{equation}
 \ell=\left\lfloor t^{5/6}(\log t)^{-2/3}\right\rfloor.
 \label{eq:finite-range-variational-scale}
\end{equation}
Then the cutoff defect in
\eqref{eq:finite-range-projection-defect} is at most \(1/2\) for all
large \(t\), and every error in
\eqref{eq:finite-range-variational-errors} is bounded by
\(C_{S,J}t^{-1/3}(\log t)^{2/3}\).  Use
\eqref{eq:finite-range-scaling-identity} to finish the proof.

Propositions~\ref{prop:finite-range-pressure} and
\ref{prop:finite-range-variational} give the two inequalities around the
same massive Bose term.  For large \(t\),
\begin{equation}
 t^{-1/3}(\log t)^{2/3}
 \leq t^{-1/27}(\log t)^{17}.
 \label{eq:finite-range-final-absorption}
\end{equation}
Combining the propositions and enlarging \(C_{S,J}\) proves
\eqref{eq:main-quantitative}, uniformly for \(a=\beta h\geq0\).

\label{prop:finite-range-general}
\begin{equation}
 \lim_{\beta\to\infty}\ \sup_{h\geq0}
 \left|
  \beta^2S\widetilde j_J f_J(\beta,S,h)
  +\frac{1}{4\pi}\operatorname{Li}_2(e^{-\beta h})
 \right|=0.
 \label{eq:main-general}
\end{equation}

\label{prop:quantitative-positive-basis}
There are constants
\(C_{S,J},t_{S,J}<\infty\) such that, for \(t\geq t_{S,J}\) and
\(h\geq0\),
\begin{equation}
 \left|
  \beta^2S\widetilde j_J f_J(\beta,S,h)
  +\frac1{4\pi}\operatorname{Li}_2(e^{-\beta h})
 \right|
 \leq C_{S,J}t^{-1/27}(\log t)^{17}.
 \label{eq:positive-basis-quantitative}
\end{equation}

\label{lem:canonical-path-spin-comparison}
There is a
constant \(C_{S,K}<\infty\), independent of \(L\), such that, for all
sufficiently large \(L\),
\begin{equation}
 H_{L,\rm nn}^{\rm ex,per}
 \leq C_{S,K}H_{L,K}^{\rm ex,per}
 \label{eq:spin-canonical-path-comparison}
\end{equation}
in the quadratic-form sense.

Use the spin-half fibres of \eqref{eq:fibre-bond-identity}, with
\(r=2S\), and let \(P_{(x,a),(y,b)}\) transpose two fibres. The product
\(\mathcal P_{\rm sym}\) of local fibre symmetrizers satisfies
\begin{equation}
 \mathcal P_{\rm sym}\bigl(1-P_{(x,a),(y,b)}\bigr)
 \mathcal P_{\rm sym}
 =\frac{2}{r^2}
  \bigl(S^2-\mathbf S_x\mathbin\cdot\mathbf S_y\bigr)\mathcal P_{\rm sym},
 \label{eq:individual-fibre-compression}
\end{equation}
by local permutation symmetry and
\(1-P_{(x,a),(y,b)}=2(\frac14-\mathbf s_{x,a}\cdot\mathbf s_{y,b})\).

Since the support generates \(\mathbb Z^2\), fix simple paths
\begin{equation}
 0=x_{\nu,0},x_{\nu,1},\ldots,x_{\nu,m_\nu}=e_\nu,
 \qquad x_{\nu,i}-x_{\nu,i-1}\in\operatorname{supp}K,
 \quad \nu=1,2.
 \label{eq:coordinate-canonical-path}
\end{equation}
These paths and all their translates embed in the torus for large \(L\).
For self-adjoint unitaries \(U_j\) with self-adjoint product
\(W=U_1\cdots U_\ell\), telescoping and Cauchy--Schwarz give
\begin{equation}
 1-W\leq\ell\sum_{j=1}^{\ell}(1-U_j),
 \label{eq:unitary-word-inequality}
\end{equation}
using \(\|(1-U)\psi\|^2=2\langle\psi,(1-U)\psi\rangle\).
The endpoint fibre transposition along
\eqref{eq:coordinate-canonical-path} is a palindromic word of length
\(2m_\nu-1\), using one fibre at each intermediate site and each path
edge at most twice. Compressing \eqref{eq:unitary-word-inequality} with
\eqref{eq:individual-fibre-compression} yields, with a harmless
overestimate of the constant,
\begin{equation}
 S^2-\mathbf S_x\mathbin\cdot\mathbf S_{x+e_\nu}
 \leq 2r^2(2m_\nu-1)
       \sum_{i=1}^{m_\nu}
       \bigl(S^2-\mathbf S_{x+x_{\nu,i-1}}
                     \mathbin\cdot\mathbf S_{x+x_{\nu,i}}\bigr).
 \label{eq:single-bond-path-comparison}
\end{equation}
Summing over \(x\) and \(\nu\) proves
\eqref{eq:spin-canonical-path-comparison}: every displacement on the
right belongs to the fixed finite support of \(K\), and its periodic
bond sum is bounded by \(H_{L,K}^{\rm ex,per}\) times the reciprocal of
its positive weight. The constant is independent of \(L\).

\label{lem:finite-variance-truncation}
There is \(R_0<\infty\) such that \(J_R\) and \(J\) have the same exchange
lattice for every \(R\geq R_0\). There are numbers \(c_R\to1\) such that, on every sufficiently large
periodic box,
\begin{equation}
 X_{J_R,L}^{\rm per}\leq X_{J,L}^{\rm per}
 \leq c_RX_{J_R,L}^{\rm per}.
 \label{eq:finite-variance-exchange-squeeze}
\end{equation}
Consequently,
\begin{equation}
 f_{J_R}(\beta,S,h)\leq f_J(\beta,S,h)
 \leq c_R f_{J_R}(c_R\beta,S,h/c_R).
 \label{eq:finite-variance-free-energy-squeeze}
\end{equation}

\label{lem:lr-local-limits}
If \(0<\sigma<2\), then
\begin{align}
 \varepsilon_J(p)&=\kappa_\sigma|p|^\sigma(1+o(1)),\qquad p\to0,
 \label{eq:lr-stable-symbol}\\
 I_J(u)&=D_\sigma u^{-2/\sigma}(1+o(1)),\qquad u\to\infty.
 \label{eq:lr-stable-return}
\end{align}
If \(\sigma=2\), then
\begin{align}
 \varepsilon_J(p)&=c_4|p|^2\log\frac1{|p|}+O(|p|^2),\qquad p\to0,
 \label{eq:lr-marginal-symbol}\\
 I_J(u)&=\frac{D_2}{u\log u}\,(1+o(1)),\qquad u\to\infty.
 \label{eq:lr-marginal-return}
\end{align}
In addition, for \(u\geq1\),
\begin{equation}
 \sup_{x\in\mathbb Z^2}\bigl(e^{-uK_J}\bigr)(0,x)
 \leq
 \begin{cases}
  Cu^{-2/\sigma},&0<\sigma<2,\\
  C(u\log(2+u))^{-1},&\sigma=2,
 \end{cases}
 \label{eq:lr-full-heat-bound}
\end{equation}

\label{lem:lr-finite-box-heat}
If \(0<\sigma<2\) and \(1\leq u\leq cL^\sigma\), then
\begin{equation}
 \left|\operatorname{Tr}_{\1^\perp}e^{-uK_{J,L}^N}-L^2I_J(u)\right|
 +\left|\operatorname{Tr} e^{-uh_{J,L}^D}-L^2I_J(u)\right|
 \leq C\mathcal E_\sigma(u,L).
 \label{eq:lr-stable-finite-box-heat}
\end{equation}
At \(\sigma=2\), if \(1\leq u\leq cL^2\) and
\(R_2(u)\leq L/4\), then
\begin{equation}
 \left|\operatorname{Tr}_{\1^\perp}e^{-uK_{J,L}^N}-L^2I_J(u)\right|
 +\left|\operatorname{Tr} e^{-uh_{J,L}^D}-L^2I_J(u)\right|
 \leq CL\sqrt{\frac{\log(2+u)}u}+C.
 \label{eq:lr-marginal-finite-box-heat}
\end{equation}
Moreover, for all \(u\geq1\),
\begin{align}
 \operatorname{Tr}_{\1^\perp}e^{-uK_{J,L}^N}
 &\leq CL^2u^{-2/\sigma},&&0<\sigma<2,
 \label{eq:lr-stable-neumann-tail}\\
 \operatorname{Tr}_{\1^\perp}e^{-uK_{J,L}^N}
 &\leq CL^2u^{-1},&&\sigma=2.
 \label{eq:lr-marginal-neumann-tail}
\end{align}

\label{lem:lr-bose-traces}
Uniformly in \(b\geq0\), for \(0<\sigma<2\),
\begin{align}
 \Phi_{J,L}^N(s,b)
 &=L^2D_\sigma t^{-\nu}
   \operatorname{Li}_{1+\nu}(e^{-b})+o(L^2t^{-\nu}),
 \label{eq:lr-stable-neumann-bose}\\
 \Phi_{J,\ell}^D(t,b)
 &\geq \ell^2D_\sigma t^{-\nu}
 \operatorname{Li}_{1+\nu}(e^{-b})-o(\ell^2t^{-\nu}).
 \label{eq:lr-stable-dirichlet-bose}
\end{align}
At \(\sigma=2\), uniformly in \(b\geq0\),
\begin{align}
 \Phi_{J,L}^N(s,b)
 &=\frac{L^2D_2}{t\log t}\operatorname{Li}_2(e^{-b})
  +o\left(\frac{L^2}{t\log t}\right),
 \label{eq:lr-marginal-neumann-bose}\\
 \Phi_{J,\ell}^D(t,b)
 &\geq\frac{\ell^2D_2}{t\log t}\operatorname{Li}_2(e^{-b})
  -o\left(\frac{\ell^2}{t\log t}\right).
 \label{eq:lr-marginal-dirichlet-bose}
\end{align}

\label{lem:lr-box-geometry}
For \(L\geq3\), the graph \(G_{J,L}^{(r)}\), and every deletion of one
of its vertices, is connected and has uniformly bounded weighted degree.
Moreover,
\begin{align}
 \operatorname{gap}(K_{J,L}^{(r)})&\geq
 \begin{cases}
  cL^{-\sigma},&0<\sigma<2,\\
  cL^{-2},&\sigma=2,
 \end{cases}
 \label{eq:lr-box-gap}\\
 \rho(G_{J,L}^{(r)})+\rho_\circ(G_{J,L}^{(r)})&\leq
 \begin{cases}
  C,&0<\sigma<2,\\
  C\log(2L),&\sigma=2.
 \end{cases}
 \label{eq:lr-box-resistance}
\end{align}

\label{prop:lr-collision}
\begin{align}
 0\leq N_{L,k}^{(r,J)}
 &\leq Ck^2(1+k+k^2L^{\sigma-2})^2
       (H_{L,k}^{(r,J)})^2,
 &&0<\sigma<2,
 \label{eq:lr-stable-collision}\\
 0\leq N_{L,k}^{(r,J)}
 &\leq Ck^6\log^3(2L)(H_{L,k}^{(r,J)})^2,
 &&\sigma=2.
 \label{eq:lr-marginal-collision}
\end{align}

\label{lem:lr-highest-weight}
\begin{equation}
 H_{m,k}^{(r,J),\mathrm{HW}}\geq c\frac{k}{m^\sigma},
 \qquad 0<\sigma\leq2.
 \label{eq:lr-highest-weight}
\end{equation}
Consequently, for every \(u>0\) and \(b\geq0\),
\begin{equation}
 \operatorname{Tr} e^{-u\mathcal H_m^{(r,J)}-b\mathcal N}
 \leq(M_m+1)\exp\{M_m e^{-cu/m^\sigma-b}\}.
 \label{eq:lr-rough-trace}
\end{equation}

\label{prop:lr-pressure}
For \(0<\sigma<2\),
\begin{equation}
 \liminf_{\beta\to\infty}\ \inf_{h\geq0}
 \left\{\beta^{1+2/\sigma}S^{2/\sigma}f_J(\beta,S,h)
 +D_\sigma\operatorname{Li}_{1+2/\sigma}(e^{-\beta h})\right\}\geq0.
 \label{eq:lr-stable-pressure-limit}
\end{equation}
At \(\sigma=2\),
\begin{equation}
 \liminf_{\beta\to\infty}\ \inf_{h\geq0}
 \left\{\beta^2S\log(\beta S)f_J(\beta,S,h)
 +D_2\operatorname{Li}_2(e^{-\beta h})\right\}\geq0.
 \label{eq:lr-marginal-pressure-limit}
\end{equation}

\label{prop:lr-variational}
For \(0<\sigma<2\),
\begin{equation}
 \limsup_{\beta\to\infty}\ \sup_{h\geq0}
 \left\{\beta^{1+2/\sigma}S^{2/\sigma}f_J(\beta,S,h)
 +D_\sigma\operatorname{Li}_{1+2/\sigma}(e^{-\beta h})\right\}\leq0.
 \label{eq:lr-stable-variational-limit}
\end{equation}
At \(\sigma=2\),
\begin{equation}
 \limsup_{\beta\to\infty}\ \sup_{h\geq0}
 \left\{\beta^2S\log(\beta S)f_J(\beta,S,h)
 +D_2\operatorname{Li}_2(e^{-\beta h})\right\}\leq0.
 \label{eq:lr-marginal-variational-limit}
\end{equation}

Use the free trial operator
\begin{equation}
 K_{J,\ell,h}^D=S\,\mathrm d\Gamma(h_{J,\ell}^D)+h\mathcal N
 \label{eq:lr-free-trial-operator}
\end{equation}
and the cutoff \(\mathcal P\) from
\eqref{eq:holstein-primakoff-cutoff}.  Adopt the notation
\(Z_0,Z_{\mathcal P},\Gamma_{\mathcal P}\) of
Lemma~\ref{lem:general-projected-entropy} with
\(A=S h_{J,\ell}^D+hI\). Equation~\eqref{eq:trial-operator-inequality}
gives
\begin{equation}
 \mathcal P H_{\ell,J,h}^D\mathcal P\leq K_{J,\ell,h}^D.
 \label{eq:lr-trial-operator-inequality}
\end{equation}

We record the estimates entering the projected entropy calculation.  In
the stable case, with \(\nu=2/\sigma>1\), domination of the killed heat
kernel by the full kernel and \eqref{eq:lr-full-heat-bound} give
\begin{align}
 \rho_*&:=\sup_x
 \bigl(e^{t h_{J,\ell}^D+b}-1\bigr)^{-1}(x,x)
 \leq Ct^{-\nu},
 \label{eq:lr-stable-local-density}\\
 1-\frac{Z_{\mathcal P}}{Z_0}
 &\leq C\ell^2t^{-2\nu}=:Q_{\ell,t}.
 \label{eq:lr-stable-projection-defect}
\end{align}
The heat-trace eigenvalue count following from
\eqref{eq:lr-full-heat-bound} also yields
\begin{align}
 E_1&:=\operatorname{Tr}\frac{2(Sh_{J,\ell}^D+h)}
 {e^{t h_{J,\ell}^D+b}-1}
 &\leq CS\ell^2t^{-1-\nu},
 \label{eq:lr-stable-energy-trace}\\
 E_2&:=\operatorname{Tr}\frac{Sh_{J,\ell}^D+h}
 {\sinh^2((t h_{J,\ell}^D+b)/2)}
 &\leq CS\ell^2t^{-1-\nu}.
 \label{eq:lr-stable-entropy-trace}
\end{align}
The integral at zero in the second estimate is finite precisely because
\(\nu>1\).  The functions of \(t\lambda+b\) in these traces decrease in
\(b\), so the bounds are uniform in the field.

For \(Q_{\ell,t}\leq1/2\), insert
\eqref{eq:lr-stable-local-density}--
\eqref{eq:lr-stable-entropy-trace} into
\eqref{eq:general-projected-free-energy}, using \(q\leq Q_{\ell,t}\).
This yields
\begin{align}
 f_{J,\ell}^D(\beta,S,h)
 \leq{}&-\frac1{\beta\ell^2}\Phi_{J,\ell}^D(t,b)
 +CS\left(t^{-1-2\nu}+\ell^2t^{-1-3\nu}\right).
 \label{eq:lr-stable-projected-bound}
\end{align}
Choose \(\ell=t^\gamma+O(1)\) with
\(1/\sigma<\gamma<2/\sigma\).  Then
\(Q_{\ell,t}=o(1)\). Relative to the leading Bose term, the two displayed
errors are \(O(t^{-\nu})\) and \(O(\ell^2t^{-2\nu})\).  Equation
\eqref{eq:lr-stable-dirichlet-bose} proves the stable box estimate. The
passage to the full lattice is made in
\eqref{eq:lr-block-variational-passage}.

At \(\sigma=2\), positivity of the nearest-neighbour bonds gives the form
comparison \(h_{J,\ell}^D\geq c h_{0,\ell}^D\), where
\(h_{0,\ell}^D\) is the unit-coupling nearest-neighbour zero-exterior
Laplacian.  The Green-function bound \eqref{eq:finite-range-local-green-bound} and
the trace estimates
\eqref{eq:finite-range-energy-sum}--\eqref{eq:finite-range-entropy-sum}
therefore apply without an upper comparison and give
\begin{align}
 1-\frac{Z_{\mathcal P}}{Z_0}
 &\leq C\frac{\ell^2\log^2(2\ell)}{t^2},
 \label{eq:lr-marginal-projection-defect}\\
 f_{J,\ell}^D(\beta,S,h)
 &\leq-\frac1{\beta\ell^2}\Phi_{J,\ell}^D(t,b)
 +CS\left(\frac{\log^2(2\ell)}{t^3}
 +\frac{\ell^2\log^2(2\ell)}{t^4}\right).
 \label{eq:lr-marginal-projected-bound}
\end{align}
With \(\ell=t^{5/6}+O(1)\), the defect tends to zero and both error terms
are \(o((\beta t\log t)^{-1})\).  Together with
\eqref{eq:lr-marginal-dirichlet-bose}, this proves the required marginal
box estimate.

It remains to pass from a Dirichlet box to the infinite system.  Tile a
large square by \(\ell\)-blocks and put the exact Dirichlet Gibbs state in
each block.  This state is invariant under rotations about the third spin
axis, hence its transverse one-spin expectations vanish.  For sites
\(x,y\) in different blocks, put
\(\rho_x=\langle S-S_x^3\rangle\).  The tensor-product state satisfies the
exact estimate
\begin{align}
 \langle S^2-\mathbf S_x\cdot\mathbf S_y\rangle
 &=S(\rho_x+\rho_y)-\rho_x\rho_y
 \leq S(\rho_x+\rho_y).
 \label{eq:lr-cross-block-bound}
\end{align}
After multiplication by \(J(y-x)\), the right side is precisely the sum
of the two pinned terms assigned to this bond by
\eqref{eq:lr-dirichlet-spin-hamiltonian}.  Thus all cross-block bonds,
including arbitrarily long ones, are controlled with no corridor and no
loss of active density.  Entropy is additive.  Incomplete outer blocks
have vanishing density, and their boundary contribution tends to zero by
\eqref{eq:summable-boundary-density}.  The Gibbs variational principle
therefore gives
\begin{equation}
 f_J(\beta,S,h)\leq f_{J,\ell}^D(\beta,S,h).
 \label{eq:lr-block-variational-passage}
\end{equation}
Combining \eqref{eq:lr-stable-projected-bound} or
\eqref{eq:lr-marginal-projected-bound} with the corresponding Dirichlet
Bose trace proves \eqref{eq:lr-stable-variational-limit} and
\eqref{eq:lr-marginal-variational-limit}.
